import React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Table.stories";
import {
  Table,
  TableBody,
  TableHead,
  TableRow,
  TableCell,
  TableSortLabel,
} from ".";

const { Basic } = composeStories(stories) as any;

describe("Table component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <Table data-testid="table">
        <TableHead data-testid="tablehead">
          <TableRow data-testid="tablerow">
            <TableCell data-testid="tablecell">
              <TableSortLabel data-testid="tablesortlabel"></TableSortLabel>
            </TableCell>
          </TableRow>
        </TableHead>
        <TableBody data-testid="tablebody"></TableBody>
      </Table>
    );
    expect(screen.getByTestId("table")).toBeTruthy();
    expect(screen.getByTestId("tablehead")).toBeTruthy();
    expect(screen.getByTestId("tablerow")).toBeTruthy();
    expect(screen.getByTestId("tablecell")).toBeTruthy();
    expect(screen.getByTestId("tablesortlabel")).toBeTruthy();
    expect(screen.getByTestId("tablebody")).toBeTruthy();
  });
});
